1	// Tập 7 · C4 · ĐOẠN C = S10–S15. Một trục thời gian chung (Aug 1991 → Oct 2026, trái → phải) cho mọi vật: thanh đứt nét "one assumed rate" →
2	// hai đường lãi khảo sát thật (V3) + hai thẻ khoản vay → lưới V1 1.833 ô (ô cuối = tuần của Tessa) → khoảng giữa hai đường rời xuống trục, phóng
3	// thành 1.833 cột khoảng chênh (V6 ngoặc nhỏ nhất / lớn nhất, vạch trung bình, chấm Tessa) → mỗi cột thành một chồng (W2 hàng + W5 đỉnh), cùng
4	// thang bó của the stack cạnh nhà → nhỏ nhất, cao nhất, trung vị, tuần cao bằng/hơn của Tessa (ít hơn 1/5). Mốc giờ chỉ từ spine.json.
5	import { setup, figure, gesture, figTag, OfferCard, WeekGrid, WeekRow, theStack, stackSet, BUNDLE_TH, modeLook, followLight, chrome, label, seg2, vbrace, dip,
6	  kf, show, pulse, C, CK, ease, lin, mix, THREE } from '/episodes/ep007/world/c4kit.js';
7	import { Ribbon } from '/toolkit/factory/world/lib3d.js';
8	
9	const SEG = '/episodes/ep007/world/c4/c-s10-s15/';
10	const RY = 0.35;                  // điểm % lãi → đơn vị (trục từ 0)
11	
12	export async function boot(res) {
13	  const poses = {
14	    wC0: { pos: [-8.6, 3.0, 9.6], tgt: [-0.6, 1.5, 0], fov: 40, chart: 0 },
15	    cC: { pos: [2.2, 3.0, 26], tgt: [2.2, 3.0, 0], fov: 20.6, chart: 1 },
16	    wRow: { pos: [-7.4, 2.9, 10.4], tgt: [1.8, 1.2, -0.8], fov: 46, chart: 0 },
17	    wEnd: { pos: [-7.6, 2.6, 7.6], tgt: [-2.4, 1.0, 0], fov: 38, chart: 0 },
18	  };
19	  const { S, D, G, cue, MV, st, O, renderer, scene, floor, key, CAM } = await setup(SEG, res, poses);
20	  const b = cue, X = S.x, N = S.weeks.length, W = X.x1 - X.x0, U = BUNDLE_TH / G.bundle_usd, GS = G.stack_total * U / (S.r30[N - 1] - S.r15[N - 1]);
21	  const xw = (i) => X.x0 + (i + 0.5) * W / N;
22	  const hm = figure(scene, { x: X.house }), stack = theStack(scene, G, { x: X.stack });
23	  stackSet(stack, G.stack_total);
24	  const glowS = new THREE.Mesh(new THREE.BoxGeometry(1.06, 15 * BUNDLE_TH + 0.1, 0.76), new THREE.MeshBasicMaterial({ color: C.warn, transparent: true, opacity: 0, depthWrite: false }));
25	  glowS.position.set(X.stack, (15 * BUNDLE_TH + 0.1) / 2, 0); scene.add(glowS);
26	  // S10.1: một mức lãi giả định = thanh ĐỨT NÉT phẳng (ink-muted, vật cố định) dọc trục thời gian, sau nhà
27	  const yA = S.assumed_rate * RY, rail = new THREE.Group(), ND = 26;
28	  for (let k = 0; k < ND; k++) { const m = new THREE.Mesh(new THREE.BoxGeometry(W / ND * 0.55, 0.06, 0.06), new THREE.MeshStandardMaterial({ color: C.muted, emissive: new THREE.Color(C.muted), emissiveIntensity: 0.45, transparent: true }));
29	    m.position.set(X.x0 + (k + 0.5) * W / ND, yA, 0.35); rail.add(m); }
30	  scene.add(rail); rail.userData.checks = { role: 'mark', key: 'assumed-rate' };
31	  // S10.2: hai thẻ khoản vay thật (V4 adapted), trên vùng đường lãi
32	  const card15 = OfferCard(scene, { x: X.cards[0], y: 4.55, w: 3.3, h: 0.72 }), card30 = OfferCard(scene, { x: X.cards[1], y: 4.55, w: 3.3, h: 0.72 });
33	  // hai đường lãi khảo sát (accent), mọi tuần
34	  const l30 = Ribbon({ color: C.accent, z: 0.3, width: 0.06, maxPts: N + 2 }), l15 = Ribbon({ color: '#8DB5FF', z: 0.3, width: 0.045, maxPts: N + 2 });
35	  scene.add(l30, l15); l30.userData.checks = { role: 'series', series: 'r30', key: 'rate-30' }; l15.userData.checks = { role: 'series', series: 'r15', key: 'rate-15' };
36	  // lưới V1 (tường sau trục), cột khoảng chênh → chồng (cùng 1.833 vật: khoảng giữa hai đường hạ xuống, rồi thành chồng)
37	  const grid = WeekGrid(scene, S.weeks, { x0: X.x0, width: W, y0: 0.3, height: 4.5, z: -0.6 });
38	  const cols = WeekRow(scene, S.extra, { x0: X.x0, width: W, z: 0.05, depth: 0.22, unit: U, name: 'gap-then-stacks' });
39	  const sp = S.r30.map((r, i) => r - S.r15[i]);
40	  // S15.1: vạch trung vị (ink-muted) dọc hàng
41	  const med = new THREE.Mesh(new THREE.BoxGeometry(1, 0.035, 0.04), new THREE.MeshBasicMaterial({ color: C.muted, transparent: true })); med.geometry.translate(0.5, 0, 0);
42	  med.position.set(X.x0, S.median * U, 0.25); scene.add(med); med.userData.checks = { role: 'mark', key: 'median-line', value: S.median };
43	  const cA = new THREE.Color(C.accent), cAd = new THREE.Color('#22355A'), cW = new THREE.Color(C.warn), cWd = new THREE.Color('#4A3F2A'), cI = new THREE.Color(C.ink);
44	  const T15 = G.stack_total;
45	
46	  function frame(t) {
47	    const pose = CAM.apply(t), cw = pose.chart, cam = CAM.cam;
48	    followLight(key, pose.tgt); modeLook(scene, floor, cw); gesture(hm, t, S.gestures);
49	    // thanh giả định: mọc trái → phải ở "one"; mờ khi đường thật vẽ; tắt khi lưới đầy
50	    const rg = lin(t, b.c0.one - 0.05, b.c0.one + 0.6), rA = (1 - 0.6 * ease(t, b.c1.every, b.c1.every + 1.0)) * (1 - ease(t, b.c2.priced, b.c2.priced + 0.5));
51	    rail.children.forEach((m, k) => { const v = Math.min(1, Math.max(0, rg * ND - k)); m.visible = v > 0.01 && rA > 0.01; m.scale.x = Math.max(0.001, v); m.material.opacity = rA; });
52	    const cardA = 1 - ease(t, b.c2.priced, b.c2.priced + 0.5);
53	    card15.set({ a: show(t, b.c1.real) * cardA }); card30.set({ a: show(t, b.c1.thirty) * cardA, band: 0 });
54	    // đường lãi: vẽ ở "every" (1,5 s); mờ dưới lưới; về ở "far"; tắt khi khoảng rời xuống trục ("gap")
55	    const dr = lin(t, b.c1.every, b.c1.every + 1.5) * (N - 1);
56	    const lA = t < b.c4.far ? 1 - 0.82 * ease(t, b.c2.priced, b.c2.priced + 0.6) : mix(0.18, 1, ease(t, b.c4.far, b.c4.far + 0.6)) * (1 - ease(t, b.c5.gap, b.c5.gap + 0.8));
57	    for (const [L, R] of [[l30, S.r30], [l15, S.r15]]) {
58	      const m = Math.floor(dr), pts = []; for (let i = 0; i <= m; i += 2) pts.push([xw(i), R[i] * RY]);
59	      if (m < N - 1 && dr > m) pts.push([xw(dr), mix(R[m], R[m + 1], dr - m) * RY]); else if (m === N - 1) pts.push([xw(N - 1), R[N - 1] * RY]);
60	      if (pts.length > 1) L.set(pts); L.visible = pts.length > 1 && lA > 0.01; L.material.opacity = lA;
61	    }
62	    // lưới V1
63	    const gA = 1 - ease(t, b.c4.far, b.c4.far + 0.6);
64	    grid.set({ fill: kf(S.fill, t), lastA: ease(t, b.c3.last - 0.05, b.c3.last + 0.3), wave: t > b.c3.earlier && t < b.c3.earlier + 1.9 ? (N - 1) * (1 - (t - b.c3.earlier) / 1.6) : null, a: gA });
65	    // cột khoảng chênh → chồng: "above" khoảng giữa hai đường (cột từ lãi 15 năm tới lãi 30 năm), "gap" hạ xuống trục + phóng ×GS/RY, "least" ≥ nửa
66	    // điểm sáng; "every" (S13.1) mỗi cột THÀNH chồng (sóng trái → phải, accent → warn); S15.2 tuần cao bằng/hơn Tessa sáng
67	    const ab = ease(t, b.c4.above - 0.05, b.c4.above + 0.5), mg = ease(t, b.c5.gap, b.c5.gap + 1.0), le = ease(t, b.c6.least - 0.05, b.c6.least + 0.4);
68	    const stk = (i) => Math.min(1, Math.max(0, (t - b.c8.every - 1.6 * i / N) / 0.5)), fw = ease(t, b.d2.fewer - 0.05, b.d2.fewer + 0.6);
69	    const mkI = (i) => (i === S.i.min ? ease(t, b.c9.six - 0.05, b.c9.six + 0.3) * (1 - ease(t, b.d1.median, b.d1.median + 0.4)) : 0)
70	      + (i === S.i.max ? ease(t, b.d0.twenty - 0.05, b.d0.twenty + 0.3) * (1 - ease(t, b.d2.fewer, b.d2.fewer + 0.4)) : 0);
71	    cols.set({ grow: ab > 0.001 ? 1 : 0, a: 0.25 + 0.75 * Math.max(mg, stk(N - 1)) + 0.4 * ab * (1 - mg),
72	      span: (i) => { const k = stk(i), g0 = [mix(S.r15[i] * RY, 0, mg), mix(S.r30[i] * RY, sp[i] * GS, mg)]; return [g0[0] * (1 - k), mix(g0[1], S.extra[i] * U, k)]; },
73	      color: (i, c) => { const k = stk(i); c.copy(cA).lerp(cAd, le * (sp[i] >= 0.5 - 1e-9 ? 0 : 0.85)); c.lerp(cW, k); if (k > 0) c.lerp(cWd, 0.8 * fw * (S.extra[i] >= T15 ? 0 : 1)); c.lerp(cI, Math.min(1, mkI(i) + (i === N - 1 ? fw : 0))); } });
74	    const mL = ease(t, b.d1.median - 0.05, b.d1.median + 0.7) * (1 - ease(t, MV.m_w15.t0, MV.m_w15.t0 + 0.4)); med.scale.x = Math.max(0.001, W * mL); med.visible = mL > 0.01;
75	    glowS.material.opacity = 0.35 * Math.max(pulse(t, b.d2.high, 1.0), pulse(t, b.d3.expensive, 0.9)); glowS.visible = glowS.material.opacity > 0.01;
76	    renderer.render(scene, cam);
77	    // ---------------- lớp phủ
78	    const log = O.begin(t, cw, cam), ok = cw >= 0.95 ? 1 : 0; log.roi = {};
79	    dip(O, 1 - ease(t, 0, 0.4));   // mở đoạn từ khoảng giữ MR1 (vẽ TRƯỚC mọi chữ)
80	    figTag(O, hm);
81	    const sc = (x, y, z = 0) => O.toScreen(x, y, z), [, yFloor] = sc(X.x0, 0, 0.05), [xL] = sc(X.x0, 0, 0.05), [xR] = sc(X.x1, 0, 0.05);
82	    // trang kiểm (coverage hồi 2): mỗi ô lưới / mỗi chồng tuần là một hình mang case = tuần
83	    if (CK.on) {
84	      if (gA > 0.5 && kf(S.fill, t) >= N) for (let i = 0; i < N; i++) O.shape({ role: 'mark', world: grid.box(i), case: S.weeks[i], series: 'weeks' });
85	      if (stk(N - 1) >= 1 && t < MV.m_w15.t1) for (let i = 0; i < N; i++) O.shape({ role: 'bar', world: [[xw(i) - W / N / 2, 0, 0.05], [xw(i) + W / N / 2, S.extra[i] * U, 0.05]], case: S.weeks[i], value: S.extra[i], series: 'extra_total' });
86	    }
87	    // S10.1: tên thanh giả định (thế giới hay đồ thị: không số)
88	    { const [x, y] = sc(X.x1, yA, 0.35), [x0] = sc(X.x0, yA, 0.35), xa = Math.min(1790, x);
89	      label(O, 'one assumed rate', xa, y - 34, { align: 'right', kind: 'name', px: 48, color: C.muted, alpha: show(t, b.c0.assumed, b.c2.priced - 0.1) });
90	      log.roi['c0.one'] = [x0 - 10, y - 20, x + 10, y + 20]; log.roi['c0.assumed'] = [xa - 480, y - 90, xa + 10, y - 20]; }
91	    // S10.2: thẻ, nhãn đường lãi
92	    for (const [card, s, cl, at, id] of [[card15, `${D('term_short')} loan`, ['term_short'], b.c1.real, 'c1.real'], [card30, `${D('term_long')} paid ${D('paid_in_short')}`, ['term_long', 'paid_in_short'], b.c1.thirty, 'c1.thirty']]) {
93	      const [x, y] = sc(card.position.x, card.position.y, 0.05);
94	      label(O, s, x, y + 16, { align: 'center', kind: 'number', px: 48, alpha: ok * show(t, at, b.c2.priced - 0.3), claims: cl });
95	      log.roi[id] = [x - 300, y - 50, x + 300, y + 50];
96	    }
97	    label(O, `every real week: ${D('term_short')} and ${D('term_long')}`, 960, 215, { align: 'center', kind: 'number', alpha: ok * show(t, b.c1.every, b.c2.priced - 0.3), claims: ['term_short', 'term_long'] });
98	    log.roi['c1.every'] = [xL, sc(0, 3.4)[1], xR, yFloor];
99	    // S10.3–S10.4: nhãn lưới; ô của Tessa + đường dẫn
100	    const g2 = b.c3.last - 0.2;
101	    label(O, `${D('principal')} priced both ways each week`, 960, 205, { align: 'center', kind: 'number', alpha: ok * show(t, b.c2.both, g2), claims: ['principal'] });
102	    label(O, `${D('n_weeks')} · ${D('first_week_short')} to ${D('last_week_month')}`, 960, 268, { align: 'center', kind: 'number', alpha: ok * show(t, b.c2.thirty, g2), claims: ['n_weeks', 'first_week_short', 'last_week_month'] });
103	    { const [gx0, gy0] = sc(X.x0, grid.top, -0.6), [gx1, gy1] = sc(X.x1, 0.3, -0.6); log.roi['c2.priced'] = [gx0, gy0, gx1, gy1]; log.roi['c2.both'] = [560, 150, 1360, 230]; log.roi['c2.thirty'] = [560, 215, 1360, 290];
104	      log.roi['c3.earlier'] = [gx0, gy0, gx1, gy1]; log.roi['c4.far'] = [gx0, gy0, gx1, gy1]; }
105	    { const [cx, cy] = sc(...grid.at(N - 1)), lA = ok * show(t, b.c3.last, b.c4.far);
106	      seg2(O, cx, cy - 12, 1700, 318, C.ink, 0.8 * lA, 3);
107	      label(O, "Tessa's week = the last · ILLUSTRATIVE", 1800, 300, { align: 'right', kind: 'name', px: 48, alpha: lA, char: 'Tessa' });
108	      log.roi['c3.last'] = [cx - 30, cy - 30, cx + 30, cy + 30]; }
109	    // S11: khoảng giữa hai đường; rời xuống trục; ngoặc nhỏ nhất / lớn nhất
110	    log.roi['c4.above'] = [xL, sc(0, 3.4)[1], xR, yFloor]; log.roi['c5.gap'] = log.roi['c4.above'];
111	    label(O, `${D('term_long')} minus ${D('term_short')} rate`, 960, 215, { align: 'center', kind: 'number', alpha: ok * show(t, b.c5.gap, b.c6.averaged - 0.35), claims: ['term_long', 'term_short'] });
112	    const brk = (i, at, z) => { const [x, y0] = sc(xw(i), 0, 0.05), [, y1] = sc(xw(i), sp[i] * GS, 0.05), a = ok * show(t, at, z); vbrace(O, x - 10, y1, y0, C.ink, a, 5, 12); return [x, y1]; };
113	    { const [x0, y0] = brk(S.i.spmin, b.c5.zero, b.c6.least), [x1, y1] = brk(S.i.spmax, b.c5.one, b.c6.least);
114	      log.roi['c5.zero'] = [x0 - 40, y0 - 20, x0 + 20, yFloor]; log.roi['c5.one'] = [x1 - 40, y1 - 20, x1 + 20, yFloor]; }
115	    label(O, `gap: ${D('spread_min')} to ${D('spread_max')}`, 960, 275, { align: 'center', kind: 'number', alpha: ok * show(t, b.c5.one, b.c6.least - 0.35), claims: ['spread_min', 'spread_max'] });
116	    // S12: vạch trung bình; nhãn; chấm Tessa
117	    { const [, ya] = sc(X.x0, S.spread_mean * GS, 0.3), avA = ok * show(t, b.c6.averaged, MV.m_w13.t0), pr = lin(t, b.c6.averaged - 0.05, b.c6.averaged + 0.6);
118	      seg2(O, xL, ya, mix(xL, xR, pr), ya, C.ink, 0.9 * avA, 4, [12, 9]); log.roi['c6.averaged'] = [xL, ya - 20, xR, ya + 20]; }
119	    label(O, `average gap: ${D('spread_mean')}`, 960, 215, { align: 'center', kind: 'number', alpha: ok * show(t, b.c6.zero, MV.m_w13.t0), claims: ['spread_mean'] });
120	    log.roi['c6.zero'] = [660, 160, 1260, 230]; log.roi['c6.least'] = [xL, sc(0, 3.9)[1], xR, yFloor];
121	    label(O, `at least half a point: ${D('share_spread_ge_050')}`, 960, 275, { align: 'center', kind: 'number', alpha: ok * show(t, b.c6.two, MV.m_w13.t0), claims: ['share_spread_ge_050'] });
122	    log.roi['c6.two'] = [500, 225, 1420, 295];
123	    { const [x, y] = sc(xw(N - 1), sp[N - 1] * GS, 0.3), a = ok * show(t, b.c7.eighth, MV.m_w13.t0), c = O.ctx;
124	      if (a > 0.01) { c.save(); c.globalAlpha = a; c.fillStyle = C.ink; c.beginPath(); c.arc(x, y, 11 + 4 * pulse(t, b.c7.above, 0.8), 0, 7); c.fill(); c.restore(); }
125	      label(O, `Tessa: ${D('spread_now')} · ILLUSTRATIVE`, 1790, y - 52, { align: 'right', kind: 'number', px: 48, alpha: a, claims: ['spread_now'], char: 'Tessa' });
126	      log.roi['c7.eighth'] = [x - 30, y - 30, x + 30, y + 30]; log.roi['c7.above'] = log.roi['c7.eighth']; }
127	    // S13–S15: chồng
128	    { const [x0] = sc(X.x0, 0, 0.05); log.roi['c8.every'] = [x0, sc(0, 3.6, 0.05)[1], xR, yFloor]; log.roi['c8.rise'] = log.roi['c8.every']; }
129	    const mark = (i, at, z, s, cl, lx, ly, align) => {
130	      const [x, y] = sc(xw(i), S.extra[i] * U, 0.05), a = ok * show(t, at, z);
131	      seg2(O, x, ly + 14, x, y - 8, C.ink, 0.85 * a, 3);
132	      label(O, s, lx, ly, { align, kind: 'number', alpha: a, claims: cl }); return [x, y];
133	    };
134	    { const [x, y] = mark(S.i.min, b.c9.six, b.d1.median, `smallest: ${D('extra_total_min')} · ${D('extra_total_min_week_short')}`, ['extra_total_min', 'extra_total_min_week_short'],
135	        sc(xw(S.i.min), 0)[0], 470, 'center');
136	      log.roi['c9.six'] = [x - 30, y - 20, x + 30, yFloor]; }
137	    { const [x, y] = mark(S.i.max, b.d0.twenty, b.d2.fewer, `tallest: ${D('extra_total_max')} · ${D('extra_total_max_week_short')}`, ['extra_total_max', 'extra_total_max_week_short'], 1810, 380, 'right');
138	      log.roi['d0.twenty'] = [x - 30, y - 20, x + 30, yFloor]; }
139	    { const [, ym] = sc(X.x0, S.median * U, 0.25); log.roi['d1.median'] = [xL, ym - 20, xR, ym + 20]; }
140	    const s15 = MV.m_w15.t0 - 0.05;
141	    label(O, `median week: ${D('extra_total_median')}`, 960, 215, { align: 'center', kind: 'number', alpha: ok * show(t, b.d1.sixteen, s15), claims: ['extra_total_median'] });
142	    log.roi['d1.sixteen'] = [660, 160, 1260, 230];
143	    // S15.2: vạch nét đứt từ đỉnh the stack qua cả hàng; nhãn
144	    { const [sx, sy] = sc(X.stack + 0.45, G.stack_total * U, 0), fA = ok * show(t, b.d2.fewer, s15);
145	      seg2(O, sx, sy, mix(sx, xR, lin(t, b.d2.fewer, b.d2.fewer + 0.6)), sy, C.ink, 0.85 * fA, 4, [14, 10]);
146	      log.roi['d2.fewer'] = [sx, sy - 30, xR, yFloor]; log.roi['d3.expensive'] = [sc(X.stack - 0.5, 0)[0], sy - 20, sx + 10, yFloor];
147	      label(O, `as tall or taller: ${D('share_extra_ge_now')}`, 960, 275, { align: 'center', kind: 'number', alpha: ok * show(t, b.d2.one, s15), claims: ['share_extra_ge_now'] });
148	      log.roi['d2.one'] = [460, 225, 1460, 295];
149	      const hA = ok * show(t, b.d2.high, s15), [tx] = sc(X.stack, 0);
150	      seg2(O, tx, 352, tx, sy - 30, C.ink, 0.8 * hA, 3);
151	      label(O, `Tessa's stack: ${D('extra_vs15_total_now')} · ILLUSTRATIVE`, 130, 335, { align: 'left', kind: 'number', alpha: hA, claims: ['extra_vs15_total_now'], char: 'Tessa' });
152	      log.roi['d2.high'] = [tx - 60, sy - 20, tx + 60, yFloor]; }
