    log.roi['d1.sixteen'] = [660, 160, 1260, 230];
    // S15.2: vạch nét đứt từ đỉnh the stack qua cả hàng; nhãn
    { const [sx, sy] = sc(X.stack + 0.45, G.stack_total * U, 0), fA = ok * show(t, b.d2.fewer, s15);
