176	// ================================================================ lớp bắt buộc: ILLUSTRATIVE (mọi khung có Tessa/Leo) + nguồn + "US only · history, not a forecast"
177	// (mọi khung: mọi số của tập là lãi khảo sát đã qua) + đối trọng (cw) dòng trên history khi có
178	export const SRC = 'Freddie Mac weekly mortgage survey';
179	// cảnh MÔ PHỎNG khoản vay của Tessa (S21–S25: tính trên lãi khảo sát của tuần 8/10/2026, không phải chuỗi lịch sử) — gates/C3.md §3 "xét tiêu đề nguồn":
180	// tiêu đề nói rõ là phép tính trên lãi của một tuần; dòng "US only · history, not a forecast" và ILLUSTRATIVE giữ nguyên (luật kênh)
181	export const SRC_SIM = (D) => `Loan math at the ${D('last_week_short')} survey rate`;
182	export function chrome(O, { illus = 1, cw = null, cwA = 1, src = SRC } = {}) {
183	  O.chrome({ illus: illus > 0.01, illusA: illus, src, hist: true, ...(cw && cwA > 0.01 ? { cw, cwA } : {}) });
