76	export function PayBar({ w = 0.8, d = 0.5, scale = 1 / 1200, name = 'bar' } = {}) {
77	  const g = new THREE.Group();
78	  const base = new THREE.Mesh(new THREE.BoxGeometry(w, 1, d), mat(TRACK.ink, { emissive: new THREE.Color(TRACK.ink), emissiveIntensity: 0.12 }));
79	  const top = new THREE.Mesh(new THREE.BoxGeometry(w, 1, d), mat(TRACK.warn, { emissive: new THREE.Color(TRACK.warn), emissiveIntensity: 0.3 }));
80	  for (const m of [base, top]) { m.castShadow = m.receiveShadow = true; g.add(m); }
81	  base.userData.checks = { role: 'bar', series: name, key: `pay-${name}` }; top.userData.checks = { role: 'bar', series: name, key: `pay-${name}-above` };
82	  g.userData = { w, d, scale };
83	  // usd: chiều cao (USD/tháng); warnAbove: mức trên đó tô warn; topA ∈ [0,1]: độ hiện phần warn; appear ∈ [0,1]
84	  g.set = ({ usd = 0, warnAbove = Infinity, topA = 1, appear = 1 } = {}) => {
85	    const h = usd * scale * appear, hb = Math.min(h, warnAbove * scale), ht = Math.max(0, h - hb);
86	    base.scale.y = Math.max(0.001, hb); base.position.y = hb / 2; base.visible = hb > 0.002;
87	    top.scale.y = Math.max(0.001, ht); top.position.y = hb + ht / 2; top.visible = ht > 0.002 && topA > 0.01;
88	    top.material.color.set(TRACK.ink).lerp(new THREE.Color(TRACK.warn), topA);
89	    base.userData.checks.value = +Math.min(usd, warnAbove).toFixed(2); top.userData.checks.value = +Math.max(0, usd - warnAbove).toFixed(2);
90	    return h;
91	  };
92	  g.topY = (usd) => usd * scale;
93	  g.set({});
94	  return g;
95	}
