101	  const seal = new THREE.Mesh(new THREE.CylinderGeometry(h * 0.3, h * 0.3, d * 1.3, 12), mat('#C9D8C4', { roughness: 0.6 }));
102	  const edge = new THREE.Mesh(new THREE.BoxGeometry(w * 0.9, d * 1.2, h * 0.08), mat('#4E7A5A')); edge.position.z = h * 0.36;
103	  const edge2 = edge.clone(); edge2.position.z = -h * 0.36;
104	  g.add(body, seal, edge, edge2);
105	  g.userData.checks = { role: 'mark', series: name, key: `bill-${name}` };
