    m.set = (i, h, a, glow = 0) => { m.visible = a > 0.01; m.position.set(xw(i), 0, 0.12); m.scale.y = Math.max(0.001, h); m.material.opacity = a; m.material.emissiveIntensity = 0.35 + 0.65 * glow; };
