    // thanh giả định: mọc trái → phải ở "one"; mờ khi đường thật vẽ; tắt khi lưới đầy
    const rg = lin(t, b.c0.one - 0.05, b.c0.one + 0.6), rA = (1 - 0.6 * ease(t, b.c1.rates, b.c1.rates + 1.0)) * (1 - ease(t, b.c2.priced, b.c2.priced + 0.5));
