      if (m < N - 1 && dr > m) pts.push([xw(dr), mix(R[m], R[m + 1], dr - m) * RY]); else if (m === N - 1) pts.push([xw(N - 1), R[N - 1] * RY]);
      if (pts.length > 1) L.set(pts); L.visible = pts.length > 1 && lA > 0.01; L.material.opacity = lA;
    }
